def count_evictions(doc, window_id):
    nodes = doc["nodes"]
    task_log_node = None
    for node in nodes:
        if node["title"] == f"Cell window {window_id}: Task log":
            task_log_node = node
            break

    if not task_log_node:
        return "Task log not found"

    count = 0
    for row in task_log_node["table"]["rows"]:
        # The 'event' column is index 7 (0: time, 1: task, 2: job, 3: priority, 4: CPU, 5: memory, 6: run time, 7: event, 8: machine)
        if row[7] == 'evict':
            count += 1
    return count

