import json

def get_machine_state(doc, window, time):
    task_log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(task_log_node)

    machines_node = node_by_title(doc, f"{window}: Machines")
    m_rows = table_rows(machines_node)
    capacity = {}
    for idx, row in m_rows:
        capacity[row['machine']] = {'cpu': int(row['CPU']), 'mem': int(row['memory']), 'fails': row['fails at'], 'returns': row['returns at']}

    # Current state
    usage = {m: {'cpu': 0, 'mem': 0} for m in capacity}
    running_tasks = {m: [] for m in capacity}

    for idx, row in rows:
        t_time = int(row['time'])
        if t_time > time:
            break

        t_id = row['task']
        event = row['event']
        machine = row['machine']

        if event == 'start':
            cpu = int(row['CPU'])
            mem = int(row['memory'])
            usage[machine]['cpu'] += cpu
            usage[machine]['mem'] += mem
            running_tasks[machine].append(t_id)
        elif event == 'finish':
            # Need the task's cpu/mem
            # Find the submit row for this task
            for idx2, row2 in rows:
                if row2['task'] == t_id and row2['event'] == 'submit':
                    cpu = int(row2['CPU'])
                    mem = int(row2['memory'])
                    break
            usage[machine]['cpu'] -= cpu
            usage[machine]['mem'] -= mem
            running_tasks[machine].remove(t_id)
        elif event == 'evict':
            for idx2, row2 in rows:
                if row2['task'] == t_id and row2['event'] == 'submit':
                    cpu = int(row2['CPU'])
                    mem = int(row2['memory'])
                    break
            usage[machine]['cpu'] -= cpu
            usage[machine]['mem'] -= mem
            running_tasks[machine].remove(t_id)
        elif event == 'fail':
            # If machine fails, all tasks on it are gone
            # (But the log should have evict/fail events for each task)
            pass

    return usage, capacity

