def get_machine_state_correct(doc, window, time):
    task_log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(task_log_node)

    machines_node = node_by_title(doc, f"{window}: Machines")
    m_rows = table_rows(machines_node)
    capacity = {}
    for idx, row in m_rows:
        capacity[row['machine']] = {'cpu': int(row['CPU']), 'mem': int(row['memory'])}

    usage = {m: {'cpu': 0, 'mem': 0} for m in capacity}
    running_tasks = {m: set() for m in capacity}

    # First, get task requirements
    task_reqs = {}
    for idx, row in rows:
        if row['event'] == 'submit':
            task_reqs[row['task']] = {'cpu': int(row['CPU']), 'mem': int(row['memory'])}

    for idx, row in rows:
        t_time = int(row['time'])
        if t_time > time:
            break

        t_id = row['task']
        event = row['event']
        machine = row['machine']

        if event == 'start':
            req = task_reqs[t_id]
            usage[machine]['cpu'] += req['cpu']
            usage[machine]['mem'] += req['mem']
            running_tasks[machine].add(t_id)
        elif event == 'finish' or event == 'evict' or event == 'fail':
            # The task must be running on some machine
            # Find which machine it was on
            found_machine = None
            for m, tasks in running_tasks.items():
                if t_id in tasks:
                    found_machine = m
                    break

            if found_machine:
                req = task_reqs[t_id]
                usage[found_machine]['cpu'] -= req['cpu']
                usage[found_machine]['mem'] -= req['mem']
                running_tasks[found_machine].remove(t_id)

    return usage, capacity

