def get_tasks_on_machine_at_time(chapter, machine_id, time):
    node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(node)
    running = set()
    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        if row['event'] == 'start' and row['machine'] == machine_id:
            running.add(row['task'])
        elif row['event'] == 'finish' and row['machine'] == machine_id:
            running.discard(row['task'])
        elif row['event'] == 'evict' and row['machine'] == machine_id:
            running.discard(row['task'])
        elif row['event'] == 'fail' and row['machine'] == machine_id:
            running.discard(row['task'])

    # Now get the resources for these tasks
    task_resources = {}
    for idx, row in rows:
        if row['event'] == 'submit':
            task_resources[row['task']] = (int(row['CPU']), int(row['memory']))

    total_cpu = 0
    total_mem = 0
    tasks_list = []
    for tid in running:
        cpu, mem = task_resources[tid]
        total_cpu += cpu
        total_mem += mem
        tasks_list.append(tid)

    return tasks_list, total_cpu, total_mem

