    node = node_by_title(doc, f"{window}: Task log")
    running = {}
    for row_idx, row in table_rows(node):
        t = int(row['time'])
        if t > time:
            break
        if row['event'] == 'start':
            # Find finish time
            finish_time = None
            for row_idx_next, row_next in table_rows(node):
                if row_next['task'] == row['task'] and row_next['event'] in ['finish', 'fail', 'evict']:
                    finish_time = int(row_next['time'])
                    break
            if finish_time is None or finish_time > time:
                running[row['task']] = row['machine']
        elif row['event'] in ['finish', 'fail', 'evict']:
            if row['task'] in running:
                del running[row['task']]
    return running

