                'cpu': int(r['CPU']),
                'mem': int(r['memory']),
                'run_time': int(r['run time']),
                'submit_time': time
            }
        log.append(r)

    # Find state just before T095 evicts at 359
    t095_event_idx = -1
    for i, r in enumerate(log):
        if int(r['time']) == 359 and r['task'] == 'T095' and 'evict' in r['event']:
