def get_all_tasks_on_machines(window):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)

    # machines[machine_id] = [(start_time, end_time, task_id, cpu, mem)]
    machines = {f"M{i:02d}": [] for i in range(1, 9)}

    task_info = {}
    for idx, row in rows:
        t_id = row['task']
        if row['event'] == 'submit':
            task_info[t_id] = {
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'run_time': int(row['run time']),
                'priority': int(row['priority'])
            }
        elif row['event'] == 'start':
            machines[row['machine']].append({
                'start': int(row['time']),
                'task': t_id,
                'cpu': task_info[t_id]['cpu'],
                'mem': task_info[t_id]['mem'],
                'run_time': task_info[t_id]['run_time']
            })
        elif row['event'] == 'evict':
            # Find the start event and truncate it
            m_id = row['machine']
            for event in machines[m_id]:
                if event['task'] == t_id and event['start'] <= int(row['time']):
                    event['end'] = int(row['time'])
        elif row['event'] == 'fail':
            m_id = row['machine']
            for event in machines[m_id]:
                if event['task'] == t_id and event['start'] <= int(row['time']):
                    event['end'] = int(row['time'])

    # For those that didn't evict/fail, end = start + run_time
    for m_id, events in machines.items():
        for event in events:
            if 'end' not in event:
                event['end'] = event['start'] + event['run_time']

    return machines

