def get_cluster_state(window, start_time, end_time):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)

    # machines[machine_id] = { 'cpu': total_cpu, 'mem': total_mem, 'tasks': {task_id: (start, end, cpu, mem)} }
    machines_info = node_by_title(doc, f"{window}: Machines")
    machine_rows = table_rows(machines_info)
    cluster = {}
    for idx, row in machine_rows:
        cluster[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'tasks': {}
        }

    task_details = {}
    for idx, row in rows:
        t_id = row['task']
        if row['event'] == 'submit':
            task_details[t_id] = {'cpu': int(row['CPU']), 'mem': int(row['memory']), 'run_time': int(row['run time'])}
        elif row['event'] == 'start':
            m_id = row['machine']
            start = int(row['time'])
            # We don't know the end yet, will find it from finish/evict/fail
            cluster[m_id]['tasks'][t_id] = [start, None, task_details[t_id]['cpu'], task_details[t_id]['mem']]
        elif row['event'] == 'finish':
            m_id = row['machine']
            if t_id in cluster[m_id]['tasks']:
                cluster[m_id]['tasks'][t_id][1] = int(row['time'])
        elif row['event'] == 'evict' or row['event'] == 'fail':
            m_id = row['machine']
            if t_id in cluster[m_id]['tasks']:
                cluster[m_id]['tasks'][t_id][1] = int(row['time'])
                # Important: task might restart. The 'start' event will create a new entry.
                # To avoid conflicts, we should store tasks as a list of intervals.

    # Correction: a task can be on a machine multiple times.
    cluster = {}
    for idx, row in machine_rows:
        cluster[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'intervals': [] # (start, end, task_id, cpu, mem)
        }

    # Use the log to build intervals
    current_tasks = {} # task_id -> (machine, start, cpu, mem)
    for idx, row in rows:
        t_id = row['task']
        time = int(row['time'])
        if row['event'] == 'start':
            m_id = row['machine']
            cpu = int(row['CPU'])
            mem = int(row['memory'])
            current_tasks[t_id] = (m_id, time, cpu, mem)
        elif row['event'] in ['finish', 'evict', 'fail']:
            if t_id in current_tasks:
                m_id, start, cpu, mem = current_tasks.pop(t_id)
                cluster[m_id]['intervals'].append((start, time, t_id, cpu, mem))

    # Handle tasks still running at the end of the log
    # The 'Queue at window end' or the log might have these.
    # Let's assume they run until at least 1200.
    for t_id, (m_id, start, cpu, mem) in current_tasks.items():
        cluster[m_id]['intervals'].append((start, 2000, t_id, cpu, mem))

    return cluster

