def get_free_resources_corrected(cluster, time, tasks_to_ignore=None):
    if tasks_to_ignore is None:
        tasks_to_ignore = set()
    free = {}
    for m_id, info in cluster.items():
        # Machine status
        if info['fail_at'] <= time < info['return_at']:
            free[m_id] = (0, 0)
            continue

        cpu_used = 0
        mem_used = 0
        for start, end, t_id, cpu, mem in info['intervals']:
            if t_id in tasks_to_ignore:
                continue
            if start <= time < end:
                cpu_used += cpu
                mem_used += mem
        free[m_id] = (info['cpu'] - cpu_used, info['mem'] - mem_used)
    return free

