def analyze_wait(window, target_task):
    logs = get_task_logs(window)
    machines_node = node_by_title(doc, f"{window}: Machines")
    machines_rows = table_rows(machines_node)

    machine_info = {}
    for idx, row in machines_rows:
        machine_info[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'fail': int(row['fails at']) if row['fails at'] != '-' else None,
            'return': int(row['returns at']) if row['returns at'] != '-' else None
        }

    task_requests = {}
    for idx, row in logs:
        if row['event'] == 'submit':
            task_requests[row['task']] = {
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'priority': int(row['priority']),
                'submit': int(row['time'])
            }

    # T152 info
    t152_req = task_requests['T152']

    # Let's check the resources on all machines from 796 to 1096.
    # We'll sample every 10 seconds.
    results = []
    for t in range(796, 1097, 10):
        current_cpu = {m: machine_info[m]['cpu'] for m in machine_info}
        current_mem = {m: machine_info[m]['mem'] for m in machine_info}

        # Account for failures
        for m, info in machine_info.items():
            if info['fail'] is not None and info['fail'] <= t:
                if info['return'] is None or info['return'] > t:
                    current_cpu[m] = 0
                    current_mem[m] = 0

        # Account for running tasks
        for idx, row in logs:
            rt = int(row['time'])
            if rt > t: continue

            # This is tricky because we need to know when tasks finish.
            # Let's find the event that stops the task.
            task = row['task']
            if row['event'] == 'start':
                # Find when it finishes or is stopped
                start_time = rt
                m = row['machine']
                # Look ahead in the logs for the end of this task
                end_time = 1201
                for idx2, row2 in logs:
                    if row2['task'] == task and (row2['event'] == 'finish' or row2['event'] == 'evict' or row2['event'] == 'fail'):
                        if int(row2['time']) > start_time:
                            end_time = int(row2['time'])
                            break

                if start_time <= t < end_time:
                    current_cpu[m] -= task_requests[task]['cpu']
                    current_mem[m] -= task_requests[task]['mem']

        # Check if T152 could fit on any machine
        fits = False
        for m in sorted(current_cpu.keys()):
            if current_cpu[m] >= t152_req['cpu'] and current_mem[m] >= t152_req['mem']:
                fits = True
                break
        results.append((t, fits, current_cpu.copy(), current_mem.copy()))

    return results

